'use client';
import HeroCarousel from './HeroCarousel';
import DetailPage from './DetailPage';
import useRegionalBranding from './useRegionalBranding';
import {RegionPicker} from './RegionalIdentity';
import {brandCaption,manualRegionHomeHref,platformOperator,type RegionalBrand,type RegionId} from '@/lib/regional-branding';
import {readDetailRoute,topicIds,type DetailRoute} from '@/lib/details';
import InformationPage,{informationPages} from './InformationPage';
import ContinuousTicker from './ContinuousTicker';

import DiscoveryPage from './DiscoveryPage';
import CompanionStories from './CompanionStories';
import MemberPage from './MemberPage';
import AuthPage from './AuthPage';
import {SystemStats,TeacherInspiration} from './RightSidebarPanels';
import SeoHead from './SeoHead';
import {useEffect,useState} from 'react';
import {BookOpen, GraduationCap, ArrowRight, ChevronRight, ChevronDown, MapPin, Bell, Menu, X, Check, Target, Shapes, Sparkles, Monitor, Users, Headphones, FileText, LibraryBig, CalendarDays, CircleHelp, Pause, Play, Layers3, Compass, LockKeyhole, CheckCircle2, Search, ExternalLink, Trophy} from 'lucide-react';
import {getRoadmaps,gradeOptions,parseGrade} from '@/lib/roadmaps';
const nav=[['Trang chủ','home'],['Lớp học Toán','classes'],['Tài liệu','materials'],['Luyện đề','practice'],['Giáo viên đồng hành','teachers'],['Bảng vàng thành tích','honors']] as const;
const faqs=[['Con nên bắt đầu từ lộ trình nào?','Hãy chọn lớp con đang học, xem mục tiêu và các bước của từng lộ trình. Có thể bắt đầu từ phần củng cố nền tảng trước khi luyện các nội dung nâng cao.'],['Lộ trình có thay đổi theo lớp học không?','Có. Khi chọn một lớp ở bên trái, tiêu đề, các thẻ lộ trình và nội dung chi tiết sẽ cùng thay đổi theo lớp được chọn.'],['Phụ huynh có thể theo dõi việc học của con không?','Không gian phụ huynh được thiết kế để theo dõi lộ trình, lịch học và phản hồi của giáo viên sau khi tài khoản được liên kết hợp lệ. Bản này đang là giao diện minh họa.'],['Tôi có thể sử dụng tài liệu và làm bài ngay không?','Đây là bản xem trước giao diện. Học liệu, tài khoản và chức năng chấm bài cần kết nối hệ thống thật trước khi đưa vào sử dụng.']];
function Brand({brand,grade}:{brand:RegionalBrand;grade:number}){return <a className="brand" href={manualRegionHomeHref(brand.id,grade)} aria-label="Toán Ôn Thi 360, trang chủ"><span className="brand-line"><GraduationCap size={42} strokeWidth={1.7}/><span className="brand-wordmark"><span className="brand-subject">TOÁN</span><b>ÔNTHI<span>360</span></b></span></span><small data-regional-caption={brand.id}>{brandCaption(brand)}</small></a>}
export default function Home({initialRegion='nationwide'}:{initialRegion?:RegionId}){
 const {region,brand,setRegion}=useRegionalBranding(initialRegion,'region');
 const regionChoice=<section className="public-region-choice" aria-label="Đơn vị theo khu vực"><RegionPicker region={region} onChange={setRegion}/><span className="public-region-name">{brandCaption(brand)}</span></section>;
 const [grade,setGrade]=useState(9),[tab,setTab]=useState('home'),[page,setPage]=useState(1),[paused,setPaused]=useState(false),[mobile,setMobile]=useState(false),[detail,setDetail]=useState<DetailRoute>({kind:'',id:'',source:'home',sourcePage:1});
 const roadmaps=getRoadmaps(grade);
 useEffect(()=>{const sync=()=>{const params=new URLSearchParams(window.location.search);setGrade(parseGrade(params.get('lop')));setPage(params.get('page')==='2'?2:1);setDetail(readDetailRoute(params));const view=params.get('muc')??'home';setTab(nav.some(n=>n[1]===view)||['login','register','roadmaps','stories','detail'].includes(view)||informationPages.some(p=>p[0]===view)?view:'not-found');setMobile(false);};sync();window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync)},[]);
 function update(nextGrade:number,nextTab=tab,nextPage=1){setPage(nextPage);setGrade(nextGrade);setTab(nextTab);setMobile(false);setDetail({kind:'',id:'',source:'home',sourcePage:1});const url=new URL(window.location.href);url.search='';url.hash='';if(region!=='nationwide')url.searchParams.set('region',region);url.searchParams.set('lop',String(nextGrade));if(nextPage>1)url.searchParams.set('page',String(nextPage));if(nextTab!=='home')url.searchParams.set('muc',nextTab);window.history.pushState({...window.history.state,detailReturnQuery:null},'',url);if(nextTab!==tab||nextPage!==page)window.scrollTo({top:0,behavior:'instant'});}
 function openDetail(kind:string,id:string){const next={kind,id,source:tab,sourcePage:page};setDetail(next);setTab('detail');setMobile(false);const url=new URL(window.location.href);url.search='';url.hash='';if(region!=='nationwide')url.searchParams.set('region',region);url.searchParams.set('muc','detail');url.searchParams.set('loai',kind);url.searchParams.set('id',id);url.searchParams.set('lop',String(grade));url.searchParams.set('tu',tab);if(page>1)url.searchParams.set('trang',String(page));window.history.pushState({...window.history.state,detailReturnQuery:url.search},'',url);window.scrollTo({top:0,behavior:'instant'});}
 function backFromDetail(){if(window.history.state?.detailReturnQuery===window.location.search)window.history.back();else update(grade,detail.source,detail.sourcePage);}
 return <><SeoHead tab={tab} grade={grade} page={page} detail={detail}/><header className="site-header"><div className="header-inner"><Brand brand={brand} grade={grade}/><button className="mobile-toggle icon-button" onClick={()=>setMobile(!mobile)} aria-expanded={mobile} aria-label="Mở menu">{mobile?<X/>:<Menu/>}</button><nav className={mobile?'main-nav open':'main-nav'} aria-label="Điều hướng chính">{nav.map(([label,key],i)=><button className={tab===key?'active':''} key={key} onClick={()=>update(grade,key)}>{i===0?<Compass size={18}/>:i===1?<BookOpen size={18}/>:i===2?<LibraryBig size={18}/>:i===3?<FileText size={18}/>:<>{key==='honors'?<Trophy size={18}/>:<Users size={18}/>}</>}<span>{label}</span></button>)}</nav><button className="button primary login" onClick={()=>update(grade,'login')}><LockKeyhole size={16}/> Đăng nhập</button></div></header>
 <main className="container">{!['home','login','register'].includes(tab)&&regionChoice}{tab==='home'?<><div className="notice"><Bell size={17}/><strong>Chào mừng đến Toán Ôn Thi 360</strong><span>Học có lộ trình · Hiểu sâu kiến thức · Tự tin tiến bộ mỗi ngày</span><a href="#roadmaps">Khám phá ngay <ArrowRight size={15}/></a></div>
 <section className="region-bar" aria-label="Thông tin theo khu vực"><RegionPicker region={region} onChange={setRegion}/><div className="ticker-window" tabIndex={0} aria-label="Nội dung thông tin khu vực"><ContinuousTicker paused={paused} key={region}>{brand.ticker}</ContinuousTicker></div><button className="icon-button" onClick={()=>setPaused(!paused)} aria-label={paused?'Chạy thông tin':'Tạm dừng thông tin'}>{paused?<Play size={16}/>:<Pause size={16}/>}</button></section>

 <div className="main-grid"><aside className="left-sidebar"><section className="panel grade-panel"><h2><Layers3/> Chọn lớp học</h2><div className="grade-grid" aria-label="Chọn lớp để xem lộ trình">{gradeOptions.map(g=><button key={g} onClick={()=>update(g)} aria-pressed={g===grade} className={g===grade?'selected':''}>Lớp {g}{g===grade&&<Check size={12}/>}</button>)}</div><img className="grade-illustration" src="/assets/toan/foundation-v6.png" alt="Học sinh cùng sách vở"/><div className="side-note"><Sparkles size={16}/><span>Một mục tiêu rõ ràng.<br/>Một hành trình phù hợp.</span></div></section><section className="panel topic-panel"><h2><Shapes/> Chuyên đề Toán</h2>{['Số và Đại số','Hình học và Đo lường','Thống kê và Xác suất','Toán trong cuộc sống'].map((t,i)=><button key={t} onClick={()=>openDetail('topic',topicIds[i])}><span className={`topic-dot t${i}`}>{['π','△','%','∞'][i]}</span>{t}<ChevronRight size={15}/></button>)}</section><div className="side-art"><img src="/assets/toan/books-detail.webp" alt="Sách và dụng cụ học Toán"/></div><section className="panel teacher-directory"><h2><Users size={20}/> Giáo viên nổi bật</h2><p className="sidebar-note">Đang chuẩn bị hồ sơ giáo viên.</p><div className="teacher-list">{['Toán tiểu học','Toán THCS','Toán THPT'].map((stage,i)=><div className="teacher-preview" key={stage}><span className={`teacher-avatar avatar-${i}`}><GraduationCap size={20}/></span><span><strong>{stage}</strong><small>Hồ sơ chưa công bố</small></span></div>)}</div><button className="button soft full" onClick={()=>update(grade,'teachers')}>Xem giáo viên <ArrowRight size={15}/></button><p className="demo-note">Vị trí minh họa, chưa phải hồ sơ thực.</p></section><TeacherInspiration/></aside>
 <div className="main-content"><HeroCarousel/>
 <section id="roadmaps" className="roadmap-section" aria-live="polite"><div className="section-heading"><div><span className="eyebrow">HỌC CÓ ĐỊNH HƯỚNG</span><h2>Lộ trình học Toán dành cho học sinh lớp {grade}</h2></div><span className="grade-tag">Lớp {grade}</span></div><p className="section-desc">Chọn mục tiêu phù hợp để khám phá từng bước trên hành trình học tập.</p><div className="roadmap-grid" id="home-roadmap-list">{roadmaps.map((r,i)=><article className={`roadmap-card ${r.theme}`} key={r.id} data-testid="roadmap-card"><div className="roadmap-body"><span className="mini-label">LỘ TRÌNH · LỚP {grade}</span><h3>{r.title}</h3><p>{r.summary}</p><div className="roadmap-picture"><img src={i===0?"/assets/toan/foundation-v6.png":i===1?"/assets/toan/geometry-v3.webp":"/assets/toan/exam-v3.webp"} alt="Minh họa hành trình học Toán"/></div><ol>{r.steps.map(s=><li key={s}>{s}</li>)}</ol><button onClick={()=>openDetail('roadmap',r.id)}>Xem lộ trình <ArrowRight size={16}/></button></div></article>)}</div><div className="home-list-actions"><button className="button soft" onClick={()=>update(grade,'roadmaps')}>Xem thêm lộ trình lớp {grade}<ArrowRight size={16}/></button></div><p className="demo-note">Nội dung lộ trình minh họa, chờ giáo viên thẩm định trước khi phát hành.</p></section>
 <section className="parent-banner"><div className="banner-icon"><Users/></div><div><span className="eyebrow">DÀNH CHO PHỤ HUYNH</span><h3>Hiểu con học gì. Cùng con tiến bộ.</h3><p>Đồng hành đúng lúc, nuôi dưỡng sự tự tin mỗi ngày.</p></div><button className="button soft" onClick={()=>openDetail('guide','companion')}>Tìm hiểu <ArrowRight size={16}/></button></section>
 <div className="audience-grid">{[['toan/foundation-v6.png','Học sinh','Chủ động khám phá'],['toan/family-v3.webp','Phụ huynh','An tâm đồng hành'],['toan/educator-v3.webp','Giáo viên','Tận tâm dẫn dắt']].map(([img,label,desc])=><article key={label}><img src={`/assets/${img}`} alt={`Minh họa ${label.toLowerCase()}`}/><div><strong>{label}</strong><span>{desc}</span></div></article>)}</div>
 <section className="shortcut chocon"><span className="shortcut-icon"><Monitor/></span><div><h3>chocon <span>· Kết nối cùng chocon</span></h3><p>Hệ thống quản lý, giám sát, giáo dục con sử dụng máy tính và bảo vệ con trên môi trường mạng.</p></div><button className="button soft" onClick={()=>openDetail('guide','chocon')}>Khám phá <ArrowRight size={16}/></button></section>
 <CompanionStories onMore={()=>update(grade,'stories')}/>
 <section className="shortcut sat"><span className="shortcut-icon"><Target/></span><div><span className="eyebrow">MỞ RỘNG CƠ HỘI</span><h3>Ôn luyện Tiếng Anh</h3><p>Mở ra cơ hội giao tiếp quốc tế và ôn thi chuyên.</p></div><a className="button soft" href="https://tienganh.onthi360.vn" target="_blank" rel="noopener noreferrer" aria-label="Khám phá Tiếng Anh, mở website ngoài trong tab mới">Khám phá Tiếng Anh <ExternalLink size={16}/></a></section>
 </div><aside className="right-sidebar"><section className="panel workspace"><div className="workspace-icon"><Monitor/></div><h2>Không gian học tập<br/>và làm việc</h2><p>Hành trình của em, sự đồng hành của gia đình và thầy cô.</p><div className="workspace-options"><span><CheckCircle2/> Lộ trình và tiến độ</span><span><CheckCircle2/> Lịch học và nhiệm vụ</span><span><CheckCircle2/> Nhận xét và kết quả</span></div><button className="button primary" onClick={()=>update(grade,'login')}><LockKeyhole size={15}/> Đăng nhập ngay</button><small>Dành cho học sinh · Phụ huynh · Giáo viên</small><div className="workspace-art" aria-hidden="true"><span className="workspace-orbit orbit-one">+</span><span className="workspace-orbit orbit-two">π</span><span className="workspace-screen"><Monitor size={106} strokeWidth={1.3}/><span>Toán 360</span></span><BookOpen className="workspace-book" size={48} strokeWidth={1.5}/></div></section><SystemStats/><section className="panel achievements"><h2><Target size={20}/> Thành tích nổi bật</h2><p className="sidebar-note">Kết quả sẽ được cập nhật từ dữ liệu đã xác minh.</p><div className="achievement-list">{[['Kết quả học tập',BookOpen],['Mục tiêu hoàn thành',CheckCircle2],['Tiến bộ theo tháng',Target]].map(([label,Icon])=>{const Symbol=Icon as typeof BookOpen;return <div className="achievement-row" key={String(label)}><Symbol size={19}/><span>{String(label)}</span><b aria-label="Chưa có dữ liệu">—</b></div>})}</div><small className="demo-note">Chưa có số liệu công bố.</small></section><section className="panel resources"><h2><LibraryBig/> Tài liệu nổi bật</h2>{[['Kiến thức trọng tâm',`Hệ thống kiến thức Toán lớp ${grade}`],['Phương pháp giải toán','Từng bước phân tích và trình bày'],['Bài tập theo chủ đề','Củng cố kiến thức sau mỗi bài']].map(([name,desc])=><button key={name} onClick={()=>update(grade,'materials')}><span className="file-icon"><FileText/></span><span><strong>{name}</strong><small>{desc}</small></span><ChevronRight size={14}/></button>)}<button className="button soft full" onClick={()=>update(grade,'materials')}>Khám phá tài liệu <ArrowRight size={15}/></button><p className="demo-note">Danh mục minh họa</p><img className="resource-art" src="/assets/toan/books-detail.webp" alt="Sách và dụng cụ học Toán"/></section><section className="panel learning-tip"><div className="tip-heading"><span className="tip-icon"><Sparkles size={18}/></span><span className="eyebrow">MẸO HỌC MỖI NGÀY</span></div><h3>Hiểu cách làm,<br/>nhớ lâu hơn.</h3><p>Thử giải thích lời giải bằng lời của mình, rồi tìm thêm một cách giải khác.</p><div className="tip-practice"><Shapes size={17}/><span>Mỗi ngày một cách nghĩ mới</span></div></section></aside></div>
 <section className="help-grid"><div className="panel faq"><div className="section-heading"><div className="heading-icon"><CircleHelp/></div><div><h2>Câu hỏi thường gặp</h2><p>Giải đáp để hành trình bắt đầu dễ dàng hơn.</p></div></div>{faqs.map(([q,a])=><details key={q}><summary>{q}<ChevronDown size={16}/></summary><p>{a}</p></details>)}</div><div className="panel support"><img src="/assets/toan/consultation-v3.webp" alt="Tư vấn viên hỗ trợ học sinh và phụ huynh học Toán"/><div className="support-copy"><span className="eyebrow">LUÔN LẮNG NGHE, LUÔN ĐỒNG HÀNH</span><h2>Tư vấn viên</h2><p>Cùng thầy cô tìm hướng đi phù hợp cho con.</p><ul><li><CheckCircle2/> Tư vấn lộ trình phù hợp</li><li><CheckCircle2/> Giải đáp thắc mắc học tập</li><li><CheckCircle2/> Hỗ trợ học sinh và phụ huynh</li></ul><button className="button primary" onClick={()=>openDetail('guide','consultation')}><Headphones size={17}/> Nhận tư vấn</button></div></div></section>
 </>:tab==='detail'||tab==='not-found'?<DetailPage route={tab==='not-found'?{kind:'',id:'',source:'home',sourcePage:1}:detail} grade={grade} onBack={backFromDetail} onNavigate={t=>update(grade,t)}/>:informationPages.some(p=>p[0]===tab)?<InformationPage tab={tab} onNavigate={t=>update(grade,t)} onHome={()=>update(grade,'home')}/>:tab==='roadmaps'||tab==='stories'?<DiscoveryPage tab={tab} grade={grade} page={page} onPage={p=>update(grade,tab,p)} onGrade={g=>update(g)} onHome={()=>update(grade,'home')} onRoadmap={r=>openDetail('roadmap',r.id)}/>:tab==='login'||tab==='register'?<AuthPage key={tab} mode={tab} onNavigate={mode=>update(grade,mode)} onHome={()=>update(grade,'home')}/>:<MemberPage page={page} onPage={p=>update(grade,tab,p)} tab={tab} title={nav.find(n=>n[1]===tab)?.[0]??'Nội dung'} grade={grade} onPreview={openDetail} onGrade={g=>update(g)} onHome={()=>update(grade,'home')}/>}
 <div className="preview-label">Bản xem trước giao diện · Học liệu và thông tin dịch vụ chưa được phát hành</div></main>
 <footer className="site-footer"><div className="container footer-grid"><div><Brand brand={brand} grade={grade}/><p>Lộ trình rõ ràng – Vững vàng tri thức.<br/>Cùng học sinh, gia đình và thầy cô<br/>xây dựng niềm vui học Toán mỗi ngày.</p></div><div><h3>Học tập</h3>{nav.slice(1,4).map(([label,key])=><button key={key} onClick={()=>{update(grade,key);window.scrollTo({top:0,behavior:'smooth'})}}>{label}</button>)}</div><div><h3>Đồng hành</h3><ul className="footer-audience-list">{['Học sinh','Phụ huynh','Giáo viên','Đơn vị giáo dục'].map(t=><li key={t}>{t}</li>)}</ul></div><div><h3>Thông tin</h3>{informationPages.map(([key,label])=><button key={key} onClick={()=>update(grade,key)}>{label}</button>)}</div></div><div className="container footer-bottom"><span>© 2026 Toán Ôn Thi 360</span><span className="local-legal-entity">{brand.companyName??'Pháp nhân địa phương: Chưa xác minh'}</span><span className="platform-operator">Tổ chức vận hành nền tảng: {platformOperator.name??platformOperator.status}</span></div><img className="footer-scene" src="/assets/toan/footer-v4.webp" alt="" aria-hidden="true"/></footer>

 </>;
}