'use client';
import {useEffect,useRef} from 'react';
import {ArrowLeft,ArrowRight,ExternalLink,BookOpen,Info,Layers3,SearchX} from 'lucide-react';
import {getDetailContent,sourceLabels,type DetailRoute} from '@/lib/details';
import CatalogMetadata from './CatalogMetadata';
import './detail.css';

export default function DetailPage({route,grade,onBack,onNavigate}:{route:DetailRoute;grade:number;onBack:()=>void;onNavigate:(tab:string)=>void}){
 const content=getDetailContent(route.kind,route.id,grade);const titleRef=useRef<HTMLHeadingElement>(null);
 useEffect(()=>{titleRef.current?.focus({preventScroll:true});},[route.kind,route.id,grade]);
 if(!content)return <section className="detail-page detail-not-found"><SearchX size={42} aria-hidden="true"/><span className="eyebrow">NỘI DUNG KHÔNG KHẢ DỤNG</span><h1 ref={titleRef} tabIndex={-1}>Không tìm thấy nội dung</h1><p>Đường dẫn này không khớp với một nội dung hiện có hoặc lớp đang chọn. Hãy quay lại danh sách để chọn lại.</p><div className="detail-actions"><button className="button soft" onClick={onBack}><ArrowLeft size={16}/>Quay lại {sourceLabels[route.source]?.toLowerCase()??'trang chủ'}</button><button className="button primary" onClick={()=>onNavigate('roadmaps')}>Xem lộ trình<ArrowRight size={16}/></button></div></section>;
 return <article className={`detail-page detail-${route.kind}`}>
  <nav className="detail-breadcrumb" aria-label="Đường dẫn nội dung"><button onClick={()=>onNavigate('home')}>Trang chủ</button><span aria-hidden="true">/</span>{route.source!=='home'&&<><button onClick={onBack}>{sourceLabels[route.source]}</button><span aria-hidden="true">/</span></>}<span aria-current="page">{content.title}</span></nav>
  <div className="detail-toolbar"><span><Layers3 size={15}/>{content.context}</span><button className="button soft" onClick={onBack}><ArrowLeft size={16}/>Quay lại {sourceLabels[route.source]?.toLowerCase()??'trang chủ'}</button></div>
  <header className="detail-hero"><div className="detail-hero-copy"><span className="eyebrow">{content.eyebrow}</span><h1 ref={titleRef} tabIndex={-1}>{content.title}</h1><p>{content.summary}</p><span className="detail-state"><span aria-hidden="true"/>Bản xem trước · Chưa phát hành</span></div><figure className="detail-hero-art"><img src={content.image} alt={content.imageAlt}/><figcaption>{route.kind==='teachers'?'Ảnh minh họa, không phải chân dung thật':'Hình minh họa cho nội dung học tập'}</figcaption></figure></header>
  <div className="detail-notice" role="note"><Info size={20}/><p>{content.notice}</p></div>
  <div className="detail-layout"><div className="detail-content">
   {content.steps&&<section className="detail-section"><div className="detail-section-heading"><BookOpen size={22}/><h2>{content.stepTitle}</h2></div><p className="detail-section-intro">Khung tham khảo để hình dung nội dung, không phải danh sách bài học đã phát hành.</p><ol className="detail-timeline">{content.steps.map((step,i)=><li key={step}><span className="detail-step-number" aria-hidden="true">{String(i+1).padStart(2,'0')}</span><div><h3>{step}</h3><p>{['Làm rõ kiến thức và điều cần tìm hiểu trước khi thực hành.','Phân tích cách làm, thử vận dụng và tự giải thích từng bước.','Nhìn lại điều đã hiểu, ghi câu hỏi và chọn phần cần ôn tiếp.'][i%3]}</p></div></li>)}</ol></section>}
   <section className="detail-section"><h2>{route.kind==='teachers'?'Hồ sơ và thông tin công bố':'Thông tin cần biết'}</h2><div className="detail-information-grid">{content.sections.map(section=><section className="detail-info-block" key={section.title}><h3>{section.title}</h3><p>{section.body}</p></section>)}</div></section>
  </div><aside className="detail-sidebar" aria-label="Thông tin bổ sung"><section className="detail-summary"><span className="eyebrow">TRƯỚC KHI BẮT ĐẦU</span><h2>{content.catalogIndex!==undefined?'Thông tin tổ chức mẫu':'Trạng thái nội dung'}</h2>{content.catalogIndex!==undefined?<CatalogMetadata tab={route.kind} index={content.catalogIndex}/>:<dl><div><dt>Phạm vi</dt><dd>{content.context}</dd></div><div><dt>Học liệu và dịch vụ</dt><dd>Chưa phát hành</dd></div><div><dt>Tài khoản và dữ liệu</dt><dd>Chưa kết nối hệ thống thật</dd></div></dl>}<p className="detail-sidebar-note">Không có đăng ký, tải tệp, làm bài, thanh toán hoặc gửi yêu cầu thật từ trang chi tiết.</p></section><section className="detail-next"><h2>Tiếp tục khám phá</h2><p>Tham khảo các nội dung khác trong bản xem trước.</p>{content.externalUrl&&<a className="button primary" href={content.externalUrl} target="_blank" rel="noopener noreferrer" aria-label="Khám phá Tiếng Anh, mở website ngoài trong tab mới">Khám phá Tiếng Anh<ExternalLink size={16}/></a>}<button className="button primary" onClick={()=>onNavigate(content.destination)}>{content.destinationLabel}<ArrowRight size={16}/></button>{content.destination!=='contact'&&<button className="detail-text-link" onClick={()=>onNavigate('contact')}>Thông tin liên hệ và hỗ trợ<ArrowRight size={15}/></button>}</section></aside></div>
 </article>;
}
