'use client';
import {useState} from 'react';
import {demoProvinces} from '@/lib/demo-provinces';
import {ArrowLeft, ArrowRight, CheckCircle2, Info, LockKeyhole, ShieldCheck} from 'lucide-react';
export default function AuthPage({mode,onNavigate,onHome}:{mode:'login'|'register';onNavigate:(mode:'login'|'register')=>void;onHome:()=>void}){
 const register=mode==='register';const [notice,setNotice]=useState<null|'preview'|'forgot'|'selection'>(null);const [role,setRole]=useState('');const [province,setProvince]=useState('');const [school,setSchool]=useState('');
 function preview(){if(register&&(!role||!province)){setNotice('selection');document.getElementById(!role?'auth-role':'auth-province')?.focus();return;}setNotice('preview')}
 return <div className={`auth-page ${register?'auth-register':'auth-login'}`}><button className="auth-back" onClick={onHome}><ArrowLeft size={16}/> Về trang chủ</button><div className="auth-shell"><aside className="auth-visual"><span className="eyebrow">TOÁN ÔN THI 360</span><h2>{register?'Cùng bắt đầu hành trình học Toán':'Chào mừng bạn trở lại'}</h2><p>Không gian kết nối học sinh, gia đình và thầy cô trên từng bước tiến.</p><img src={register?'/assets/toan/foundation-v6.png':'/assets/toan/family-v3.webp'} alt={register?'Minh họa học sinh sẵn sàng học Toán':'Minh họa phụ huynh đồng hành cùng học sinh'}/><div className="auth-benefits"><span><CheckCircle2 size={16}/> Học theo mục tiêu</span><span><CheckCircle2 size={16}/> Đồng hành mỗi ngày</span></div></aside><section className="auth-form-panel" aria-labelledby="auth-form-title"><div className="auth-title-icon"><LockKeyhole size={24}/></div><h1 id="auth-form-title">{register?'Tạo tài khoản':'Đăng nhập'}</h1><p className="auth-intro">{register?'Thông tin tạo tài khoản trong bản thiết kế.':'Tiếp tục hành trình học tập và làm việc của bạn.'}</p><div className="auth-demo" role="note"><Info size={19}/><p><strong>Giao diện thử nghiệm, chưa kết nối xác thực.</strong><br/>{register?'Chỉ thử vai trò, tỉnh/thành mẫu và tên trường giả định; không gửi hoặc lưu.':'Các ô thông tin đang khóa. Không nhập mật khẩu hay thông tin cá nhân thật.'}</p></div><form onSubmit={e=>{e.preventDefault();preview()}} noValidate>{register&&<><div className="auth-choice-grid"><div><label htmlFor="auth-role">Vai trò <span aria-hidden="true">*</span></label><select id="auth-role" value={role} onChange={e=>setRole(e.target.value)} aria-invalid={notice==='selection'&&!role} aria-describedby="auth-choice-note"><option value="">Chọn vai trò (mẫu)</option><option value="student">Học sinh</option><option value="parent">Phụ huynh</option><option value="teacher">Giáo viên</option></select></div><div><label htmlFor="auth-province">Tỉnh/thành <span aria-hidden="true">*</span></label><select id="auth-province" value={province} onChange={e=>setProvince(e.target.value)} aria-invalid={notice==='selection'&&!province} aria-describedby="auth-choice-note"><option value="">Chọn tỉnh/thành mẫu</option>{demoProvinces.map(p=><option key={p.value} value={p.value}>{p.label}</option>)}</select></div></div><p id="auth-choice-note" className="auth-choice-note">Tỉnh/thành A/B/C là mẫu; vai trò không cấp quyền thật.</p><label htmlFor="auth-school">Tên trường (nhập thử)</label><input id="auth-school" value={school} onChange={e=>setSchool(e.target.value)} placeholder="Ví dụ: Trường minh họa A" maxLength={120} autoComplete="off" aria-describedby="auth-school-note"/><p id="auth-school-note" className="auth-choice-note">Chỉ nhập tên giả định; không gửi hoặc lưu.</p><label htmlFor="auth-name">Họ và tên</label><input id="auth-name" disabled placeholder="Chưa mở nhập thông tin" autoComplete="off"/></>}<label htmlFor="auth-email">{register?'Email':'Email hoặc tên đăng nhập'}</label><input id="auth-email" type={register?'email':'text'} disabled placeholder="Chưa mở nhập tài khoản" autoComplete="off"/><label htmlFor="auth-password">Mật khẩu</label><input id="auth-password" type="password" disabled placeholder="Chưa mở nhập mật khẩu" autoComplete="off"/>{register?<><label htmlFor="auth-confirm">Nhập lại mật khẩu</label><input id="auth-confirm" type="password" disabled placeholder="Chưa mở xác nhận mật khẩu" autoComplete="off"/><p className="auth-legal">Bản xem trước không tạo tài khoản hoặc ghi nhận chấp thuận.</p></>:<button type="button" className="auth-forgot" onClick={()=>setNotice('forgot')}>Quên mật khẩu?</button>}<button type="submit" className="button primary auth-submit">{register?'Xem trước đăng ký':'Xem trước đăng nhập'}<ArrowRight size={16}/></button></form>{notice&&<p className="auth-status" role="status">{notice==='selection'?'Hãy chọn vai trò và tỉnh/thành mẫu để xem trước đăng ký. Không nhập thông tin thật.':notice==='forgot'?'Chưa mở khôi phục mật khẩu. Không có email hoặc mã xác nhận nào được gửi.':'Chưa kết nối hệ thống xác thực. Không có thông tin nào được gửi và chưa có tài khoản hay phiên đăng nhập được tạo.'}</p>}<p className="auth-switch">{register?'Đã có tài khoản?':'Chưa có tài khoản?'} <button onClick={()=>{setNotice(null);setSchool('');onNavigate(register?'login':'register')}}>{register?'Đăng nhập':'Đăng ký'}</button></p><p className="auth-safety"><ShieldCheck size={15}/> Không thu thập thông tin trong bản xem trước</p></section></div></div>;
}
