import {getCatalogCards} from '@/lib/catalog';
import TeacherDirectory from './TeacherDirectory';
import CatalogMetadata from './CatalogMetadata';
import {ArrowRight, CheckCircle2, Layers3} from 'lucide-react';

export default function SectionCatalog({tab,title,grade,page,onPage,onPreview,onHome}:{tab:string;title:string;grade:number;page:number;onPage:(page:number)=>void;onPreview:(kind:string,id:string)=>void;onHome:()=>void}){
 if(tab==='teachers')return <TeacherDirectory page={page} onPage={onPage} onPreview={onPreview}/>;
 const all=getCatalogCards(tab,grade);const pageSize=4;const totalPages=Math.ceil(all.length/pageSize);const current=Math.min(Math.max(page,1),totalPages);const start=(current-1)*pageSize;const cards=all.slice(start,start+pageSize);
 return <section className="section-catalog" aria-labelledby="member-title"><div className="catalog-intro catalog-intro-compact"><span className="sample-badge">DỮ LIỆU MẪU</span><p>Minh họa nội dung, chưa phát hành dịch vụ hoặc học liệu thực.</p><span className="catalog-count">{start+1}–{Math.min(start+pageSize,all.length)} / {all.length} mục</span></div><div className="section-card-grid" aria-live="polite">{cards.map((card,index)=><article className="section-card" key={card.title}><div className="section-card-heading"><span className="mini-label">{card.label}</span><h3>{card.title}</h3><p>{card.summary}</p></div><div className="section-card-image"><img src={card.image} alt={`Minh họa ${card.title.toLowerCase()}`}/><span>Minh họa</span></div><div className="section-card-body"><CatalogMetadata tab={tab} index={start+index}/><ul>{card.points.map(point=><li key={point}><CheckCircle2 size={15}/><span>{point}</span></li>)}</ul><button className="button primary" onClick={()=>onPreview(tab,card.id)}>{card.cta}<ArrowRight size={16}/></button></div></article>)}</div><nav className="catalog-pagination" aria-label={`Phân trang ${title}`}><span>Trang {current}/{totalPages} · 4 mục mỗi trang</span><div><button onClick={()=>onPage(current-1)} disabled={current===1} aria-label="Trang trước">‹</button>{Array.from({length:totalPages},(_,i)=>i+1).map(n=><button key={n} onClick={()=>onPage(n)} aria-label={`Trang ${n}`} aria-current={n===current?'page':undefined}>{n}</button>)}<button onClick={()=>onPage(current+1)} disabled={current===totalPages} aria-label="Trang sau">›</button></div></nav><div className="catalog-back"><Layers3 size={19}/><span>Muốn chọn mục tiêu học tập trước?</span><button onClick={onHome}>Khám phá lộ trình <ArrowRight size={15}/></button></div></section>;
}
