import {getDetailContent,type DetailRoute} from './details';
export function seoFor(tab='home',grade=9,page=1,detail?:Pick<DetailRoute,'kind'|'id'>){
 if(tab==='detail'||tab==='not-found'){const content=detail&&tab==='detail'?getDetailContent(detail.kind,detail.id,grade):null;return {title:`${content?.title??'Không tìm thấy nội dung'} | Toán Ôn Thi 360`,description:content?`${content.summary} ${content.notice}`:'Đường dẫn không khớp với nội dung hiện có. Bản xem trước chưa phát hành dịch vụ.'};}

 const sections:Record<string,[string,string]>={about:['Về Toán Ôn Thi 360','Định hướng học Toán có lộ trình, kết nối học sinh, gia đình và giáo viên.'],terms:['Điều khoản sử dụng','Dự thảo khung điều khoản, chưa có hiệu lực; cần xác minh và phê duyệt.'],privacy:['Chính sách bảo mật','Khung chính sách đang chờ xác minh hệ thống thực tế, chưa có hiệu lực.'],contact:['Liên hệ và hỗ trợ','Hướng dẫn chuẩn bị câu hỏi; kênh hỗ trợ chính thức chưa được cấu hình.'],roadmaps:['Danh sách lộ trình Toán','Khám phá các lộ trình học Toán minh họa theo lớp và mục tiêu.'],stories:['Câu chuyện đồng hành','Các tình huống minh họa về học sinh, gia đình và giáo viên cùng học Toán.'],home:['Lộ trình học Toán','Khám phá lộ trình học Toán, tài liệu và luyện đề cho học sinh, phụ huynh và giáo viên.'],classes:['Lớp học Toán','Tìm hiểu các lớp Toán nền tảng, chuyên đề và tư duy theo lớp học.'],materials:['Tài liệu Toán','Khám phá sổ tay kiến thức, phiếu bài tập và hướng dẫn học Toán.'],practice:['Luyện đề Toán','Khám phá các nhóm đề ôn tập theo chương, tổng hợp và tư duy.'],teachers:['Giáo viên đồng hành','Tìm hiểu không gian giáo viên đồng hành cùng học sinh học Toán.'],honors:['Bảng vàng thành tích','Xem bố cục bảng vàng theo lớp và tỉnh/thành với dữ liệu minh họa.'],login:['Đăng nhập','Giao diện đăng nhập thử nghiệm, chưa kết nối xác thực.'],register:['Đăng ký','Giao diện đăng ký thử nghiệm, chưa tạo tài khoản thật.']};
 const entry=sections[tab]??sections.home;const account=['login','register'].includes(tab);const generic=account||['about','terms','privacy','contact'].includes(tab);return {title:`${entry[0]}${generic?'':` lớp ${grade}`}${page>1?` · Trang ${page}`:''} | Toán Ôn Thi 360`,description:`${entry[1]} ${account?'Không nhập thông tin cá nhân thật.':'Bản xem trước minh họa, chưa phát hành dịch vụ.'}`};
}
